from collections.abc import Callable


def pad_fmtstr(getfmt: Callable[[int], str], offset: int, padlen: int) -> bytes:
    """Pad a format string to align with the stack.

    Args:
        getfmt: A callable that takes an index and returns a format string.
        offset: 在 printf 中第几个位置对应对齐后的输入缓冲区起始地址
        padlen: 输入缓冲区需要多少字节才能与字节边界对齐
    Example:
        >>> pad_fmtstr(lambda idx: f"%*73$c%{idx}$n", 28, 2)
        b'%*73$c%30$n..-----'
    """
    for idx in range(offset, offset + 10):  # 不断加大 data 所在的栈偏移量
        fmt = getfmt(idx).encode()
        dot = b"." * padlen
        pad = b"-" * (-len(fmt) % 8)
        if len(fmt + pad) == (idx - offset) * 8:
            return fmt + dot + pad
    raise ValueError("format string is invalid")
